#include <Arduino.h>
#include <Wire.h>

static const uint8_t LCD_ADDR = 0x27;
static const uint8_t BL = 0x08;

static bool expanderWrite(uint8_t value) {
  Wire.beginTransmission(LCD_ADDR);
  Wire.write((uint8_t)(value | BL));
  const int err = Wire.endTransmission();
  return err == 0;
}

void setup() {
  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(115200);
  Serial1.println("INO_LCD_BOOT");

  Wire.setSDA(4);
  Wire.setSCL(5);
  Wire.begin();
  Serial1.println("INO_LCD_I2C_READY");

  int ping = -1;
  for (int i = 0; i < 3; ++i) {
    Wire.beginTransmission(LCD_ADDR);
    Wire.write((uint8_t)BL);
    ping = Wire.endTransmission();
    if (ping == 0) break;
    delay(5);
  }

  Serial1.print("INO_LCD_PING ");
  Serial1.println(ping);

  const bool initOk = (ping == 0);
  bool stepOk = false;
  if (initOk) {
    stepOk = expanderWrite(0x00);
  }

  Serial1.print("INO_LCD_INIT ");
  Serial1.println(initOk ? 1 : 0);
  Serial1.print("INO_LCD_STEP 0 OK ");
  Serial1.println(stepOk ? 1 : 0);
  Serial1.println("INO_LCD_DONE");
}

void loop() {
  delay(100);
}

